using namespace std;
struct AhoCorasick {
    vector<array<int,26>> go; vector<int> fail, out;
    AhoCorasick(): go(1), fail(1,0), out(1,0){}
    void addPat(const string& s, int id){
        int cur=0;
        for(char c:s){ int ch=c-'a'; if(!go[cur][ch]){go[cur][ch]=go.size();go.push_back({});fail.push_back(0);out.push_back(0);} cur=go[cur][ch]; }
        out[cur]|=(1<<id);
    }
    void build(){
        queue<int> q;
        for(int c=0;c<26;c++) if(go[0][c]) q.push(go[0][c]);
        while(!q.empty()){
            int u=q.front();q.pop();
            for(int c=0;c<26;c++){
                int v=go[u][c];
                if(v){fail[v]=go[fail[u]][c];out[v]|=out[fail[v]];q.push(v);}
