from collections import deque

def build_automaton(patterns):
    trie = [{'next': {}, 'fail': 0, 'out': []}]
    for p in patterns:
        node = 0
        for ch in p:
            if ch not in trie[node]['next']:
                trie.append({'next': {}, 'fail': 0, 'out': []})
                trie[node]['next'][ch] = len(trie) - 1
            node = trie[node]['next'][ch]
        trie[node]['out'].append(p)
    q = deque(trie[0]['next'].values())
    while q:
        u = q.popleft()
        for ch, v in trie[u]['next'].items():
            f = trie[u]['fail']
            while f and ch not in trie[f]['next']:
                f = trie[f]['fail']
            trie[v]['fail'] = trie[f]['next'].get(ch, 0) if trie[f]['next'].get(ch, 0) != v else 0
            trie[v]['out'] += trie[trie[v]['fail']]['out']
            q.append(v)
    return trie

def search(text, patterns):
    trie = build_automaton(patterns)
    node, hits = 0, []
    for i, ch in enumerate(text):
        while node and ch not in trie[node]['next']:
            node = trie[node]['fail']
        node = trie[node]['next'].get(ch, 0)
        for p in trie[node]['out']:
            hits.append((i - len(p) + 1, p))
    return hits

